cd /work && python3 - <<'EOF'
import json, re, pathlib

# 1) JSON validity + exact CONTRACT schema keys
d = json.load(open('deliverable/estrategia.json'))
expected = {"prazo_habilitacao_divergencia","contagem","credito_fiduciario","credito_quirografario",
            "divergencia_de_valor","fianca_do_socio","voto","objecao_ao_plano_prazo","acoes_imediatas"}
print("JSON valid. keys match schema:", set(d.keys()) == expected, "| prazo:", d["prazo_habilitacao_divergencia"], "| contagem:", d["contagem"])
print("acoes count:", len(d["acoes_imediatas"]))

# 2) Overclaims must be gone
rc = open('deliverable/resposta_cliente.md').read()
for banned in ["risco de sanção", "a lei permite completar a atualização depois", "desconhecida** — depende da data do deferimento"]:
    print(f"removed '{banned}':", banned not in rc)

# 3) Citation sweep: every law-token cited anywhere in deliverable/
allowed = {
 "art. 6º, §§4º","art. 6º §4º","art. 6º §7º-A","art. 7º §1º","art. 7º §2º","art. 9º","art. 10",
 "art. 41","art. 45","art. 49 §1º","art. 49 §3º","art. 52 §1º","art. 55","art. 58 §1º","art. 59",
 "art. 189 §1º","art. 224 §1º","Súmula 581","Tema 1.051","Tema 885","REsp 1.333.349",
}
tokens=set()
for p in pathlib.Path('deliverable').glob('*'):
    t=open(p).read()
    for m in re.finditer(r'(?:arts?\.|Súmula|Tema|REsp)[^.;\n]{0,80}', t):
        tokens.add(m.group(0)[:90])
suspicious=[]
for tk in sorted(tokens):
    nums = re.findall(r'\d+[º°]', tk)
    if not nums and not re.search(r'Súmula|Tema|REsp', tk): suspicious.append(('odd',tk))
print("distinct citation fragments:", len(tokens))

# 4) Confirm LC 123 / art. 6º caput / CPC 224 caput only appear labeled
for p in pathlib.Path('deliverable').glob('*'):
    t=open(p).read()
    for kw in ["LC 123","Lei Complementar","caput"]:
        for i,line in enumerate(t.splitlines(),1):
            if kw in line:
                lab = any(w in line for w in ["fora do acervo","não integram a biblioteca","não está reproduzida","não reproduzido","não está na biblioteca","não está expressa","não reproduzida","premissa","Premissa","caput*, da LRF","art. 189, *caput*","art. 189 caput","*caput* —","não está reproduzida na biblioteca","caput,"])
                if not lab: print(f"  CHECK {p.name}:{i}: {line[:110]}")
EOF

